        input_names=['x', 'w'], output_names=['y'],
        header='#include "mlx/backend/metal/kernels/steel/gemm/gemm_nax.h"',
        source=f'''
        using namespace mlx::steel;
        constexpr short SM = {bm // wm};
        constexpr short SN = {bn // wn};
        uint sg = simdgroup_index_in_threadgroup;
        uint row = threadgroup_position_in_grid.y * {bm} + (sg / {wn}) * SM;
        uint col = threadgroup_position_in_grid.x * {bn} + (sg % {wn}) * SN;
        auto tile = gemm_loop<T, SM, SN, 32, {bk}, false, true, true, true, true>(
            x + row * K, w + col * K, K, K, K, K / {bk}, SM, SN);
        tile.store(y + row * N + col, N);
        ''')

def timed(f, count=10):
    mx.eval(f())
    times=[]
    for _ in range(count):
        mx.synchronize()
        start=time.perf_counter()
        mx.eval(f())
        mx.synchronize()
        times.append(time.perf_counter()-start)
    return statistics.median(times)*1e3

model,_=load('Qwen/Qwen3-0.6B')
ws=[model.layers[0].self_attn.q_proj.weight,
    mx.concatenate([model.layers[0].self_attn.q_proj.weight,model.layers[0].self_attn.k_proj.weight,model.layers[0].self_attn.v_proj.weight]),
    mx.concatenate([model.layers[0].mlp.gate_proj.weight,model.layers[0].mlp.up_proj.weight]),
    model.layers[0].mlp.down_proj.weight]
mx.eval(ws)
for m in [16,64,256]:
    for w in ws:
        n,k=w.shape
        x=mx.random.normal((m,k)).astype(mx.bfloat16)
        mx.eval(x)
        ref=x@w.T
        mx.eval(ref)
        base=timed(lambda:x@w.T)
        print('shape',m,n,k,'mlx',base,flush=True)
        for bm,bn,bk,wm,wn in [(16,64,32,1,2),(16,128,32,1,4),(16,64,64,1,2),(16,128,64,1,4),(16,32,32,1,1),(32,64,32,2,2),(64,64,32,2,2)]:
            if bm>m: continue
            kernel=make_kernel(bm,bn,bk,wm,wn)
            def f():
                return kernel(inputs=[x,w],template=[('T',mx.bfloat16),('K',k),('N',n)],
                    grid=(n//bn*wm*wn*32,m//bm,1),threadgroup=(wm*wn*32,1,1),
                    output_shapes=[(m,n)],output_dtypes=[mx.bfloat16])[0]
            try:
                out=f()
                err=mx.max(mx.abs(out.astype(mx.float32)-ref.astype(mx.float32))).item()
                val=timed(f)
                print(' tile',bm,bn,bk,wm,wn,'ms',val,'ratio',base/val,'err',err,flush=True)
            except Exception as e:
                print(type(e).__name__,str(e)[:1500],flush=True)
                sys.exit(1)

