import mlx.core as mx
from pathlib import Path

def make_kernel(bm,bn):
    return mx.fast.metal_kernel(name=f'split_mma_{bm}_{bn}',
        input_names=['x','w'],output_names=['y'],
        header=Path('.tmp/mma_header.h').read_text(),
        source=f'''
        using namespace mlx::steel;
        constexpr short RM = {bm//8};
        constexpr short RN = {bn//8};
        uint row = threadgroup_position_in_grid.y * {bm};
        uint col = threadgroup_position_in_grid.x * {bn};
        uint part = threadgroup_position_in_grid.z;
        short2 sc = BaseMMAFrag<float,8,8>::get_coord(thread_index_in_simdgroup);
        MMATile<float, RM, RN> accum;
        MMATile<float, RM, 1> aa;
        MMATile<float, 1, RN> bb;
        #pragma clang loop unroll(disable)
        for (int kk = 0; kk < KP; kk += 8) {{
            #pragma clang loop unroll(full)
            for (short i=0; i<RM; ++i) {{
                BaseMMAFrag<float,8,8>::load(aa.frag_at(i,0),
                    x + (row + i*8 + sc.y)*K + part*KP + kk + sc.x, K, 1);
            }}
            #pragma clang loop unroll(full)
            for (short j=0; j<RN; ++j) {{
                BaseMMAFrag<float,8,8>::load(bb.frag_at(0,j),
                    w + (col + j*8 + sc.x)*K + part*KP + kk + sc.y, 1, K);
            }}
            tile_matmad(accum, aa, bb, accum);
        }}
        accum.template store<float,1,1>(y + part*M*N + (row+sc.y)*N + col+sc.x, N);
        ''')

def multiply(x,w,parts,bm=8,bn=32,kernel=None):
    m,k=x.shape
