"""Decode Q/K normalization and RoPE, retaining MLX's BF16 rounding.

The model-independent position table is generated with the model's own RoPE
in FP32. It contains no prompt data. Normalization accumulates in FP32 and
rounds to BF16 both before and after the learned scale, as MLX does.
"""
import mlx.core as mx

LIMIT=65536

_kernel=mx.fast.metal_kernel(
    name='qwen_qk_norm_rope',
    input_names=['qkv','qw','kw','trig','position','eps'],
    output_names=['qout','kout'],
    source=r'''
    uint head = threadgroup_position_in_grid.y;
    uint lane = thread_index_in_simdgroup;
    uint d = lane * 4;
    uint base = head * 128 + d;
    float a = float(qkv[base]);
    float b = float(qkv[base+1]);
    float c = float(qkv[base+2]);
    float e = float(qkv[base+3]);
    float sum = simd_sum(a*a + b*b + c*c + e*e);
    float inv = metal::rsqrt(sum / 128.0f + eps);
    uint trigbase = uint(position) * 128;
    #pragma clang loop unroll(full)
    for (uint j=0; j<4; ++j) {
        uint dim = d+j;
        float v = float(qkv[base+j]);
        float w = head < 16 ? float(qw[dim]) : float(kw[dim]);
        float n = float(T(float(T(v * inv)) * w));
        float partner = simd_shuffle_xor(n, ushort(16));
        float co = trig[trigbase + (dim & 63)];
        float si = trig[trigbase + (dim & 63) + 64];
        float out = dim < 64 ? n*co-partner*si : n*co+partner*si;
        if (head < 16) qout[head*128+dim] = T(out);
        else kout[(head-16)*128+dim] = T(out);
    }
    ''')

def make_table(rope):
    basis=mx.concatenate([mx.ones((1,1,LIMIT,64),mx.float32),
                          mx.zeros((1,1,LIMIT,64),mx.float32)],axis=-1)
    return rope(basis,offset=0)

def qk(qkv,qw,kw,trig,position,eps):
    return _kernel(inputs=[qkv,qw,kw,trig,position,eps],template=[('T',mx.bfloat16)],
                   grid=(32,24,1),threadgroup=(32,1,1),
                   output_shapes=[(1,16,1,128),(1,8,1,128)],
                   output_dtypes=[mx.bfloat16,mx.bfloat16])

